export function guideVisibleTo(entry:GuideEntry,audience:GuideAudience,featureVisible:(key:string)=>boolean){
 if(entry.audiences&&!entry.audiences.includes(audience))return false;
 if(entry.featureKey&&!featureVisible(entry.featureKey)&&audience!=="platform_owner")return false;
 return entry.status!=="future";
}
export function searchGuides(query:string,entries:GuideEntry[]){const q=query.trim().toLowerCase();if(!q)return[];return entries.map(entry=>{const hay=[entry.title,entry.summary,entry.why,...entry.keywords,...entry.steps,...entry.examples].join(" ").toLowerCase();const tokens=q.split(/\s+/).filter(Boolean);const score=(hay.includes(q)?10:0)+tokens.reduce((n,t)=>n+(hay.includes(t)?1:0),0);return{entry,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.entry.title.localeCompare(b.entry.title)).slice(0,8).map(x=>x.entry)}
